const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var cordoba_airport = ee.Geometry.Point([-64.208, -31.323]);
  var startDate = '2023-04-26';
  var endDate = '2023-04-27';

  // 2. Data Acquisition - ECMWF ERA5 for temperature
  var era5 = ee.ImageCollection('ECMWF/ERA5/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(cordoba_airport);

  // Check collection size
  var size = era5.size().getInfo();
  print(`ERA5 Images: ${size}`);

  if (size === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Get temperature image and convert from Kelvin to Celsius
  var tempImg = era5.first().select('mean_2m_air_temperature');
  var tempCelsius = tempImg.subtract(273.15);

  // 3. Check valid pixels
  var pixelCount = tempCelsius.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cordoba_airport,
    scale: 1000,
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo();

  print(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // 4. Get temperature value
  var maxTemp = tempCelsius.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: cordoba_airport,
    scale: 1000,
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo();

  print(`Max temperature: ${maxTemp.toFixed(1)}°C`);

  // 5. Validation & Final Answer
  if (maxTemp === null || maxTemp === undefined || !isFinite(maxTemp)) {
    print("<answer>C3</answer>");
  } else if (maxTemp > 60 || maxTemp < -60) { // Unrealistic temperature range
    print("<answer>C3</answer>");
  } else if (maxTemp > 40) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
